CREATE TABLE engineering_orders(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),baseline_id TEXT NOT NULL REFERENCES order_baselines(id),number TEXT NOT NULL UNIQUE,revision INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'draft',required_date TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '',lines_json TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES employees(id),released_by TEXT REFERENCES employees(id),released_at TEXT,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,UNIQUE(baseline_id,revision));
CREATE TABLE engineering_purchase_links(order_id TEXT PRIMARY KEY REFERENCES purchase_orders(id),engineering_id TEXT NOT NULL REFERENCES engineering_orders(id));
CREATE TRIGGER engineering_lock BEFORE UPDATE ON engineering_orders WHEN OLD.status='released' BEGIN SELECT RAISE(ABORT,'已下达工程单保留原版本，请新建修订'); END;
CREATE TABLE work_tasks(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),kind TEXT NOT NULL CHECK(kind IN ('task','installation','issue')),title TEXT NOT NULL,owner_id TEXT NOT NULL REFERENCES employees(id),due_date TEXT NOT NULL,status TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',location TEXT NOT NULL DEFAULT '',blocking INTEGER NOT NULL DEFAULT 0,resolution TEXT NOT NULL DEFAULT '',acceptance TEXT NOT NULL DEFAULT '',created_by TEXT NOT NULL REFERENCES employees(id),version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE warehouse_locations(id TEXT PRIMARY KEY,code TEXT NOT NULL UNIQUE,warehouse TEXT NOT NULL,name TEXT NOT NULL,category TEXT NOT NULL DEFAULT 'purchase',usable INTEGER NOT NULL DEFAULT 1 CHECK(usable IN (0,1)));
INSERT INTO warehouse_locations VALUES('unassigned','UNASSIGNED','待核对','待分配库位','purchase',1);
ALTER TABLE stock_movements ADD COLUMN location_id TEXT NOT NULL DEFAULT 'unassigned' REFERENCES warehouse_locations(id);
CREATE TABLE warehouse_operations(id TEXT PRIMARY KEY,number TEXT NOT NULL UNIQUE,kind TEXT NOT NULL,product_id TEXT NOT NULL REFERENCES products(id),source_id TEXT REFERENCES warehouse_locations(id),destination_id TEXT REFERENCES warehouse_locations(id),quantity REAL NOT NULL,reference TEXT NOT NULL,note TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES employees(id),created_at TEXT NOT NULL);
CREATE TABLE stock_counts(id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id),location_id TEXT NOT NULL REFERENCES warehouse_locations(id),expected REAL NOT NULL,counted REAL NOT NULL,fingerprint TEXT NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',created_by TEXT NOT NULL REFERENCES employees(id),posted_by TEXT REFERENCES employees(id),version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE equipment_assets(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),delivery_line_id TEXT NOT NULL REFERENCES delivery_lines(id),serial TEXT NOT NULL UNIQUE,name TEXT NOT NULL,location TEXT NOT NULL,warranty_start TEXT NOT NULL,warranty_end TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '',created_by TEXT NOT NULL REFERENCES employees(id),version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE return_cases(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),delivery_line_id TEXT NOT NULL REFERENCES delivery_lines(id),kind TEXT NOT NULL CHECK(kind IN ('return','exchange','repair')),quantity REAL NOT NULL CHECK(quantity>0),reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'requested',replacement_product_id TEXT REFERENCES products(id),location_id TEXT REFERENCES warehouse_locations(id),resolution TEXT NOT NULL DEFAULT '',responsibility TEXT NOT NULL DEFAULT '',sales_by TEXT REFERENCES employees(id),received_by TEXT REFERENCES employees(id),received_at TEXT,created_by TEXT NOT NULL REFERENCES employees(id),version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE crm_leads(id TEXT PRIMARY KEY,name TEXT NOT NULL,company TEXT NOT NULL,contact TEXT NOT NULL,phone TEXT NOT NULL DEFAULT '',source TEXT NOT NULL,owner_id TEXT NOT NULL REFERENCES employees(id),status TEXT NOT NULL DEFAULT 'new',next_date TEXT NOT NULL,next_action TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '',customer_id TEXT REFERENCES customers(id),created_by TEXT NOT NULL REFERENCES employees(id),version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE crm_opportunities(id TEXT PRIMARY KEY,lead_id TEXT NOT NULL REFERENCES crm_leads(id),customer_id TEXT NOT NULL REFERENCES customers(id),project_id TEXT REFERENCES projects(id),name TEXT NOT NULL,owner_id TEXT NOT NULL REFERENCES employees(id),stage TEXT NOT NULL DEFAULT 'discovery',expected_minor INTEGER, currency TEXT NOT NULL CHECK(currency IN ('CNY','USD')),expected_date TEXT NOT NULL,next_action TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '',created_by TEXT NOT NULL REFERENCES employees(id),version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE project_budgets(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),currency TEXT NOT NULL CHECK(currency IN ('CNY','USD')),amount_minor INTEGER NOT NULL CHECK(amount_minor>=0),note TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES employees(id),version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(project_id,currency));
CREATE TABLE project_expenses(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),category TEXT NOT NULL,amount_minor INTEGER NOT NULL CHECK(amount_minor>0),currency TEXT NOT NULL CHECK(currency IN ('CNY','USD')),record_date TEXT NOT NULL,reference TEXT NOT NULL UNIQUE,note TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES employees(id),version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE operation_files(id TEXT PRIMARY KEY,entity TEXT NOT NULL,entity_id TEXT NOT NULL,file_name TEXT NOT NULL,mime TEXT NOT NULL,content BLOB NOT NULL,created_by TEXT NOT NULL REFERENCES employees(id),created_at TEXT NOT NULL);
CREATE INDEX work_tasks_project ON work_tasks(project_id,kind,status);
CREATE INDEX work_tasks_owner ON work_tasks(owner_id,due_date);
CREATE INDEX location_stock ON stock_movements(location_id,product_id);
CREATE INDEX operation_files_entity ON operation_files(entity,entity_id);
